<?php
declare(strict_types=1);require __DIR__.'/includes/bootstrap.php';require __DIR__.'/includes/auth.php';require __DIR__.'/includes/project_manager.php';require_permission('project_tasks.manage');verify_csrf();$pdo=db();$action=(string)($_POST['action']??'');$taskId=(int)($_POST['task_id']??0);$q=$pdo->prepare('SELECT project_id FROM project_tasks WHERE id=?');$q->execute([$taskId]);$projectId=(int)$q->fetchColumn();if(!$projectId)redirect('projects.php');if($action==='check_add'){$txt=trim((string)($_POST['item_text']??''));if($txt!=='')$pdo->prepare('INSERT INTO project_task_checklist(task_id,item_text) VALUES (?,?)')->execute([$taskId,$txt]);}elseif($action==='check_toggle'){$cid=(int)($_POST['id']??0);$pdo->prepare('UPDATE project_task_checklist SET is_done=1-is_done,completed_at=CASE WHEN is_done=0 THEN NOW() ELSE NULL END WHERE id=? AND task_id=?')->execute([$cid,$taskId]);}elseif($action==='dep_add'){$dep=(int)($_POST['depends_on_task_id']??0);if($dep&&$dep!==$taskId)$pdo->prepare('INSERT IGNORE INTO project_task_dependencies(task_id,depends_on_task_id) VALUES (?,?)')->execute([$taskId,$dep]);}elseif($action==='comment_add'){$body=trim((string)($_POST['body']??''));if($body!=='')$pdo->prepare('INSERT INTO project_comments(project_id,task_id,user_id,body) VALUES (?,?,?,?)')->execute([$projectId,$taskId,(int)$_SESSION['user_id'],$body]);}redirect('project_task_form.php?id='.$taskId);
